CREATE OR REPLACE FUNCTION public.cpa_assert_reviewed_question_retirements(p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 envelope jsonb; manifest jsonb; document text; active_release record;
 approved text[]; missing text[]; actual_classifications jsonb; retired_id text;
begin
 -- Same transaction lock as the importer: compare-and-swap cannot race another
 -- import between checking the original active release and replacing its pointer.
 perform pg_advisory_xact_lock(7261202609080502);
 envelope:=p_payload->'retirement';
 if jsonb_typeof(envelope) is distinct from 'object'
  or jsonb_typeof(envelope->'manifest_document') is distinct from 'string'
  or coalesce(envelope->>'manifest_sha256','') !~ '^[a-f0-9]{64}$'
  then raise exception 'Exact retirement manifest document and SHA256 required'; end if;
 document:=envelope->>'manifest_document';
 if encode(sha256(convert_to(document,'UTF8')),'hex') is distinct from envelope->>'manifest_sha256'
  then raise exception 'Retirement manifest SHA256 mismatch'; end if;
 manifest:=document::jsonb;
 if manifest->>'version' is distinct from '1'
  or manifest->>'artifact_type' is distinct from 'question_bank_retirement_manifest'
  or jsonb_typeof(manifest->'authorization') is distinct from 'string'
  or btrim(manifest->>'authorization')=''
  or manifest->>'historical_versions_and_learning_attempts' is distinct from 'preserve'
  or coalesce(manifest->>'expected_active_source_file_hash','') !~ '^[a-f0-9]{64}$'
  or coalesce(manifest->>'candidate_source_file_hash','') !~ '^[a-f0-9]{64}$'
  or manifest->>'candidate_source_file_hash' is distinct from p_payload->>'source_file_hash'
  or jsonb_typeof(p_payload->'source_document') is distinct from 'string'
  then raise exception 'Invalid or unbound retirement authorization'; end if;
 select r.id,r.source_file_hash into active_release from public.cpa_question_bank_releases r where r.status='active';
 if not found or active_release.id::text is distinct from manifest->>'expected_active_release_id'
  or active_release.source_file_hash is distinct from manifest->>'expected_active_source_file_hash'
  then raise exception 'Active question release changed; retirement compare-and-swap refused'; end if;
 if jsonb_typeof(manifest->'retired_set_ids') is distinct from 'array'
  or jsonb_array_length(manifest->'retired_set_ids')=0
  or exists(select 1 from jsonb_array_elements(manifest->'retired_set_ids') j where jsonb_typeof(j)<>'string' or btrim(j#>>'{}')='')
  then raise exception 'Nonempty exact retired set IDs required'; end if;
 select array_agg(j order by j) into approved from jsonb_array_elements_text(manifest->'retired_set_ids') j;
 if cardinality(approved)<>(select count(distinct j) from unnest(approved) j)
  then raise exception 'Duplicate retired set IDs'; end if;
 if jsonb_typeof(p_payload->'sets') is distinct from 'array'
  then raise exception 'Retirement target bank required'; end if;
 select coalesce(array_agg(i.set_id order by i.set_id),array[]::text[]) into missing
 from public.cpa_question_bank_release_items i where i.release_id=active_release.id
 and not exists(select 1 from jsonb_array_elements(p_payload->'sets') s where s->>'id'=i.set_id);
 if missing is distinct from approved then raise exception 'Retired set IDs must exactly equal omitted active sets'; end if;
 actual_classifications:=public.cpa_get_learning_classifications(active_release.id);
 foreach retired_id in array approved loop
  if not exists(select 1 from jsonb_array_elements(actual_classifications) c where c->>'source_set_id'=retired_id)
   or exists(select 1 from jsonb_array_elements(actual_classifications) c where c->>'source_set_id'=retired_id and c->>'question_style'<>'standard')
   or (select count(*) from jsonb_array_elements(actual_classifications) c where c->>'source_set_id'=retired_id)
      <>(select count(*) from public.cpa_question_bank_release_items i join public.cpa_subquestion_versions q on q.set_version_id=i.set_version_id where i.release_id=active_release.id and i.set_id=retired_id)
   then raise exception 'Only completely classified standard sets may use reviewed retirement'; end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.cpa_get_question_version_with_source_metadata(p_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v record; r record; item record; q record; c record; f record;
 result jsonb; source_set jsonb; candidate jsonb; normalized_source jsonb;
 previous_source jsonb; source_q jsonb; source_c jsonb; source_f jsonb; source_ref jsonb;
 source_document jsonb; matches int; source_position bigint; document_count int:=0; candidate_hash text;
 target_path text[]; value jsonb; source_common jsonb; stored_common jsonb;
begin
 result:=public.cpa_get_question_version_document(p_version_id);
 if result is null then return null; end if;
 select s.set_id,s.content_hash,s.applicability,s.sealed_at into strict v
 from public.cpa_question_set_versions s where s.id=p_version_id;

 -- Do not select the newest release. Every document attached to this exact
 -- version must be valid and agree, including retained historical releases.
 for r in
  select ri.set_id,ri.position,rr.source_document,rr.source_file_hash,rr.status,rr.published_at
  from public.cpa_question_bank_release_items ri
  join public.cpa_question_bank_releases rr on rr.id=ri.release_id
  where ri.set_version_id=p_version_id and rr.source_document is not null
 loop
  if r.set_id is distinct from v.set_id or v.sealed_at is null
   or r.status not in ('active','retired') or r.published_at is null then
   raise exception 'Private source metadata requires an exact sealed release/version binding';
  end if;
  if encode(sha256(convert_to(r.source_document,'UTF8')),'hex') is distinct from r.source_file_hash then
   raise exception 'Private source metadata source file hash mismatch';
  end if;
  source_document:=r.source_document::jsonb;
  if jsonb_typeof(source_document) is distinct from 'array' then
   raise exception 'Private source metadata source document must be an array';
  end if;
  select count(*)::int,jsonb_agg(s.value)->0,min(s.ordinality) into matches,candidate,source_position
  from jsonb_array_elements(source_document) with ordinality s(value,ordinality) where s.value->>'id'=v.set_id;
  if matches<>1 then raise exception 'Private source metadata needs exactly one source set ID'; end if;
  if source_position is distinct from r.position::bigint then
   raise exception 'Private source metadata release item position mismatch';
  end if;
  normalized_source:=jsonb_set(candidate-'status','{verification}',(candidate->'verification')-'review_status');
  candidate_hash:=encode(sha256(convert_to(jsonb_build_object('question_set',normalized_source,
   'applicability',v.applicability)::text,'UTF8')),'hex');
  if candidate_hash is distinct from v.content_hash then
   raise exception 'Private source metadata version content hash mismatch';
  end if;
  if document_count>0 and normalized_source is distinct from previous_source then
   raise exception 'Private source metadata is ambiguous across releases';
  end if;
  previous_source:=normalized_source;
  source_set:=candidate;
  document_count:=document_count+1;
 end loop;
 -- Truly document-less legacy versions keep their historical normalized DTO.
 -- A present but broken document never takes this fallback.
 if document_count=0 then return result; end if;

 -- The source hash binds the archived document to the version. It does not by
 -- itself prove that reconstructed ordinary fields still match normalized rows.
 -- Check those fields without replacing them, allowing only lifecycle labels
 -- and the private DTO's documented optional-null/default normalization.
 source_common:=jsonb_strip_nulls(jsonb_set(source_set-'source_refs'-'subquestions'-'status',
  '{verification}',(source_set->'verification')-'review_status'));
 stored_common:=jsonb_strip_nulls(jsonb_set(result-'source_refs'-'subquestions'-'status',
  '{verification}',(result->'verification')-'review_status'));
 if source_common is distinct from stored_common then
  raise exception 'Private source metadata ordinary set fields mismatch';
 end if;

 if jsonb_typeof(source_set->'source_refs') is distinct from 'array'
  or jsonb_typeof(source_set->'subquestions') is distinct from 'array' then
  raise exception 'Private source metadata source arrays are invalid';
 end if;
 if jsonb_array_length(source_set->'source_refs')<>jsonb_array_length(result->'source_refs')
  or jsonb_array_length(source_set->'subquestions')<>jsonb_array_length(result->'subquestions') then
  raise exception 'Private source metadata source ID coverage mismatch';
 end if;
 for item in select a.value,a.ordinality from jsonb_array_elements(result->'source_refs') with ordinality a loop
  select count(*)::int,jsonb_agg(s.value)->0 into matches,source_ref
  from jsonb_array_elements(source_set->'source_refs') s(value) where s.value->>'id'=item.value->>'id';
  if matches<>1 then raise exception 'Private source metadata source reference ID mismatch'; end if;
  if jsonb_strip_nulls(source_ref-'source_span') is distinct from jsonb_strip_nulls(item.value-'source_span') then
   raise exception 'Private source metadata ordinary source reference fields mismatch';
  end if;
  value:=source_ref->'source_span';
  if value is not null and value<>'null'::jsonb then
   if jsonb_typeof(value)<>'string' then raise exception 'Private source_span must be a string'; end if;
   if item.value ? 'source_span' and item.value->'source_span' is distinct from value then
    raise exception 'Private source_span would overwrite normalized metadata';
   end if;
   result:=jsonb_set(result,array['source_refs',(item.ordinality-1)::text,'source_span'],value);
  end if;
 end loop;

 for q in select a.value,a.ordinality from jsonb_array_elements(result->'subquestions') with ordinality a loop
  select count(*)::int,jsonb_agg(s.value)->0 into matches,source_q
  from jsonb_array_elements(source_set->'subquestions') s(value) where s.value->>'id'=q.value->>'id';
  if matches<>1 then raise exception 'Private source metadata subquestion ID mismatch'; end if;
  source_common:=jsonb_strip_nulls(source_q-'criteria');
  source_common:=jsonb_set(source_common,'{answer_slots}',coalesce(source_common->'answer_slots','[]'::jsonb));
  if source_common is distinct from jsonb_strip_nulls(q.value-'criteria') then
   raise exception 'Private source metadata ordinary subquestion fields mismatch';
  end if;
  if jsonb_typeof(source_q->'criteria') is distinct from 'array'
   or jsonb_array_length(source_q->'criteria')<>jsonb_array_length(q.value->'criteria') then
   raise exception 'Private source metadata criterion ID coverage mismatch';
  end if;
  for c in select a.value,a.ordinality from jsonb_array_elements(q.value->'criteria') with ordinality a loop
   select count(*)::int,jsonb_agg(s.value)->0 into matches,source_c
   from jsonb_array_elements(source_q->'criteria') s(value) where s.value->>'id'=c.value->>'id';
   if matches<>1 then raise exception 'Private source metadata criterion ID mismatch'; end if;
   if jsonb_strip_nulls(source_c-'critical_facts') is distinct from jsonb_strip_nulls(c.value-'critical_facts') then
    raise exception 'Private source metadata ordinary criterion fields mismatch';
   end if;
   if jsonb_typeof(source_c->'critical_facts') is distinct from 'array'
    or jsonb_array_length(source_c->'critical_facts')<>jsonb_array_length(c.value->'critical_facts') then
    raise exception 'Private source metadata fact ID coverage mismatch';
   end if;
   for f in select a.value,a.ordinality from jsonb_array_elements(c.value->'critical_facts') with ordinality a loop
    select count(*)::int,jsonb_agg(s.value)->0 into matches,source_f
    from jsonb_array_elements(source_c->'critical_facts') s(value) where s.value->>'id'=f.value->>'id';
    if matches<>1 then raise exception 'Private source metadata fact ID mismatch'; end if;
    if jsonb_strip_nulls(source_f-'scope') is distinct from jsonb_strip_nulls(f.value-'scope') then
     raise exception 'Private source metadata ordinary fact fields mismatch';
    end if;
    value:=source_f->'scope';
    if value is not null and value<>'null'::jsonb then
     if jsonb_typeof(value)<>'string' then raise exception 'Private fact scope must be a string'; end if;
     if f.value ? 'scope' and f.value->'scope' is distinct from value then
      raise exception 'Private scope would overwrite normalized metadata';
     end if;
     target_path:=array['subquestions',(q.ordinality-1)::text,'criteria',(c.ordinality-1)::text,
      'critical_facts',(f.ordinality-1)::text,'scope'];
     result:=jsonb_set(result,target_path,value);
    end if;
   end loop;
  end loop;
 end loop;
 return result;
end
$function$

CREATE OR REPLACE FUNCTION public.cpa_import_learning_question_bank(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_bank jsonb; v_entry jsonb; v_hash text; v_entries jsonb:='[]'; v_rows jsonb; v_native record;
begin
  if jsonb_typeof(p_payload->'learning_classifications') is distinct from 'array'
    or jsonb_typeof(p_payload->'learning_topics') is distinct from 'array'
    then raise exception 'Complete learning catalog required with bank import'; end if;
  v_bank:=public.cpa_import_question_bank(p_payload);
  for v_entry in select j from jsonb_array_elements(p_payload->'learning_classifications') j loop
    select q.content_hash into v_hash from public.cpa_question_bank_release_items ri
      join public.cpa_question_set_versions q on q.id=ri.set_version_id
      where ri.release_id=(v_bank->>'release_id')::uuid and ri.set_id=v_entry->>'set_id';
    if not found then raise exception 'Learning source not present in imported release'; end if;
    if v_entry ? 'source_content_hash' and v_entry->>'source_content_hash' is distinct from v_hash
      then raise exception 'Learning source content hash mismatch'; end if;
    select sq.authored_question_style,sq.authored_topic_ids,sq.prompt into v_native
      from public.cpa_question_bank_release_items ri join public.cpa_subquestion_versions sq on sq.set_version_id=ri.set_version_id
      join public.cpa_subquestions s on s.id=sq.subquestion_id
      where ri.release_id=(v_bank->>'release_id')::uuid and ri.set_id=v_entry->>'set_id' and s.code=v_entry->>'subquestion_id';
    if not found then raise exception 'Learning source question not present in imported release'; end if;
    if v_native.authored_question_style is not null then
      if v_entry->>'question_style' is distinct from v_native.authored_question_style
        or (select array_agg(t order by t) from jsonb_array_elements_text(v_entry->'topic_ids') t)
          is distinct from (select array_agg(t order by t) from unnest(v_native.authored_topic_ids) t)
        or (v_native.authored_question_style='standard' and v_entry->>'standalone_prompt' is distinct from v_native.prompt)
        then raise exception 'Learning catalog differs from authored question metadata'; end if;
    end if;
    v_entries:=v_entries||jsonb_build_array(v_entry||jsonb_build_object('source_content_hash',v_hash));
  end loop;
  v_rows:=public.cpa_import_learning_classifications(jsonb_build_object('release_id',v_bank->>'release_id',
    'topics',p_payload->'learning_topics','entries',v_entries));
  return v_bank||jsonb_build_object('learning_classification_count',jsonb_array_length(v_rows));
end $function$

CREATE OR REPLACE FUNCTION public.cpa_import_learning_question_bank_with_retirements(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_bank jsonb; v_entry jsonb; v_hash text; v_entries jsonb:='[]'; v_rows jsonb; v_native record;
begin
  if jsonb_typeof(p_payload->'learning_classifications') is distinct from 'array'
    or jsonb_typeof(p_payload->'learning_topics') is distinct from 'array'
    then raise exception 'Complete learning catalog required with bank import'; end if;
  v_bank:=public.cpa_import_question_bank_with_retirements(p_payload);
  for v_entry in select j from jsonb_array_elements(p_payload->'learning_classifications') j loop
    select q.content_hash into v_hash from public.cpa_question_bank_release_items ri
      join public.cpa_question_set_versions q on q.id=ri.set_version_id
      where ri.release_id=(v_bank->>'release_id')::uuid and ri.set_id=v_entry->>'set_id';
    if not found then raise exception 'Learning source not present in imported release'; end if;
    if v_entry ? 'source_content_hash' and v_entry->>'source_content_hash' is distinct from v_hash
      then raise exception 'Learning source content hash mismatch'; end if;
    select sq.authored_question_style,sq.authored_topic_ids,sq.prompt into v_native
      from public.cpa_question_bank_release_items ri join public.cpa_subquestion_versions sq on sq.set_version_id=ri.set_version_id
      join public.cpa_subquestions s on s.id=sq.subquestion_id
      where ri.release_id=(v_bank->>'release_id')::uuid and ri.set_id=v_entry->>'set_id' and s.code=v_entry->>'subquestion_id';
    if not found then raise exception 'Learning source question not present in imported release'; end if;
    if v_native.authored_question_style is not null then
      if v_entry->>'question_style' is distinct from v_native.authored_question_style
        or (select array_agg(t order by t) from jsonb_array_elements_text(v_entry->'topic_ids') t)
          is distinct from (select array_agg(t order by t) from unnest(v_native.authored_topic_ids) t)
        or (v_native.authored_question_style='standard' and v_entry->>'standalone_prompt' is distinct from v_native.prompt)
        then raise exception 'Learning catalog differs from authored question metadata'; end if;
    end if;
    v_entries:=v_entries||jsonb_build_array(v_entry||jsonb_build_object('source_content_hash',v_hash));
  end loop;
  v_rows:=public.cpa_import_learning_classifications(jsonb_build_object('release_id',v_bank->>'release_id',
    'topics',p_payload->'learning_topics','entries',v_entries));
  return v_bank||jsonb_build_object('learning_classification_count',jsonb_array_length(v_rows),'retirement_manifest_sha256',p_payload#>>'{retirement,manifest_sha256}','retirement_manifest',(p_payload#>>'{retirement,manifest_document}')::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.cpa_import_question_bank(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_variable
declare
 bank jsonb; item record; sq record; source_item record; req_item record; crit_item record; fact_item record; cite_item record;
 s jsonb; q jsonb; c jsonb; version_id uuid; logical_id uuid; sub_version_id uuid; source_id uuid; requirement_id uuid; criterion_id uuid;
 release_id uuid; content_hash text; input_hash text; existing_report jsonb; source_document text; existing_document text; existing_file_hash text; set_points int; sub_points int; revision_no int;
 decision jsonb; facts jsonb; slots jsonb; actor_id uuid; evidence text; order_position int; review_hash text; versions jsonb;
begin
 bank:=p_payload->'sets'; evidence:=p_payload->>'evidence'; actor_id:=nullif(p_payload->>'actor_user_id','')::uuid;
 if jsonb_typeof(bank) is distinct from 'array' or jsonb_array_length(bank)=0 then raise exception 'Nonempty question bank required'; end if;
 if evidence is null or btrim(evidence)='' then raise exception 'Review evidence required'; end if;
 -- Supabase service_role has auth schema USAGE but need not have auth.users
 -- SELECT. The release/review actor FKs validate existence without broadening
 -- access to the authentication table or making this importer SECURITY DEFINER.
 if p_payload->>'source_file_hash' is null or p_payload->>'bank_content_hash' is null or p_payload->>'public_content_hash' is null then raise exception 'Import hashes required'; end if;
 -- Preserve the selected UTF-8 source verbatim. These checks establish file
 -- identity and JSON assembly only; they do not re-review question content.
 if p_payload->'source_document' is not null and p_payload->'source_document'<>'null'::jsonb then
  if jsonb_typeof(p_payload->'source_document') is distinct from 'string' then raise exception 'Source document must be text'; end if;
  source_document:=p_payload->>'source_document';
  if encode(sha256(convert_to(source_document,'UTF8')),'hex') is distinct from p_payload->>'source_file_hash' then raise exception 'Source document file hash mismatch'; end if;
  if source_document::jsonb is distinct from bank then raise exception 'Source document does not match imported sets'; end if;
 end if;
 input_hash:=encode(sha256(convert_to(jsonb_build_object('sets',bank,'applicability',coalesce(p_payload->'applicability','{}'))::text,'UTF8')),'hex');
 -- Serialize all imports, revision allocation and active-pointer replacement.
 perform pg_advisory_xact_lock(7261202609080502);
 select r.id,r.validation_report,r.source_document,r.source_file_hash into release_id,existing_report,existing_document,existing_file_hash from public.cpa_question_bank_releases r where r.bank_content_hash=p_payload->>'bank_content_hash';
 if found then
  if existing_report->>'input_hash' is distinct from input_hash then raise exception 'Import hash reused for different content'; end if;
  if source_document is not null and (existing_document is distinct from source_document or existing_file_hash is distinct from p_payload->>'source_file_hash') then raise exception 'Import content already exists with a different source document'; end if;
  return jsonb_build_object('release_id',release_id,'set_count',jsonb_array_length(bank),'reused',true,'question_versions',
   (select jsonb_agg(jsonb_build_object('set_id',i.set_id,'set_version_id',i.set_version_id) order by i.position) from public.cpa_question_bank_release_items i where i.release_id=release_id));
 end if;
 insert into public.cpa_question_bank_releases(release_no,status,source_file_hash,source_document,bank_content_hash,public_content_hash,validation_report,created_by)
 values((select coalesce(max(release_no),0)+1 from public.cpa_question_bank_releases),'draft',p_payload->>'source_file_hash',source_document,p_payload->>'bank_content_hash',p_payload->>'public_content_hash',jsonb_build_object('input_hash',input_hash,'hash_format','postgres-jsonb-sha256-v1','source_import','selected final snapshot; no content re-review','source_validation',coalesce(p_payload->>'source_validation','source import; no content re-review'),'quote_hash_policy','declared values preserved; actual UTF-8 SHA256 stored separately'),actor_id)
 returning id into release_id;

 for item in select value,ordinality::int as position from jsonb_array_elements(bank) with ordinality loop
  s:=item.value;
  if s->>'schema_version' is distinct from '3.0' or s->>'type' is distinct from 'linked_question_set'
   or s->>'status' is distinct from 'published' or s#>>'{verification,review_status}' is distinct from 'verified'
   or s#>'{verification,calculation_required}' is distinct from 'false'::jsonb then
   raise exception 'Only verified, published, non-calculation v3 content can be imported';
  end if;
  if jsonb_typeof(s->'subquestions') is distinct from 'array' or jsonb_array_length(s->'subquestions') not between 1 and 10
   or jsonb_typeof(s->'source_refs') is distinct from 'array' or jsonb_array_length(s->'source_refs')=0 then raise exception 'Incomplete set'; end if;
  facts:=s#>'{shared_context,facts}';
  if jsonb_typeof(facts) is distinct from 'array' then raise exception 'Invalid shared facts'; end if;
  if exists(select 1 from jsonb_array_elements(s->'subquestions') sub where sub ? 'question_style' or sub ? 'topic_ids') then
    if exists(select 1 from jsonb_array_elements(s->'subquestions') sub where
      jsonb_typeof(sub->'question_style') is distinct from 'string' or sub->>'question_style' not in ('standard','case')
      or jsonb_typeof(sub->'topic_ids') is distinct from 'array')
      then raise exception 'Every authored question requires style and topics'; end if;
    if (select count(distinct sub->>'question_style') from jsonb_array_elements(s->'subquestions') sub)<>1
      then raise exception 'Authored source cannot mix learning styles'; end if;
    if (s#>>'{subquestions,0,question_style}'='case' and jsonb_array_length(facts)=0)
      or (s#>>'{subquestions,0,question_style}'='standard' and jsonb_array_length(facts)<>0)
      then raise exception 'Authored question style and shared facts mismatch'; end if;
  end if;
  if exists(select 1 from jsonb_array_elements(facts) f where jsonb_typeof(f)<>'object' or f->>'id' is null or jsonb_typeof(f->'text') is distinct from 'string' or f->'scoreable' is distinct from 'false'::jsonb or f-array['id','text','scoreable']<>'{}'::jsonb) then raise exception 'Shared facts contain nonpublic fields'; end if;
  if exists(select 1 from jsonb_array_elements_text(s#>'{classification,tags}') tag
   join lateral jsonb_array_elements(s->'subquestions') sub on true
   join lateral jsonb_array_elements_text(sub->'model_answer') answer on true
   where public.cpa_normalize_fact(tag)=public.cpa_normalize_fact(answer)) then raise exception 'Model answer leaked in public tags'; end if;
  perform public.cpa_json_text_array(s->'learning_order');
  if jsonb_array_length(s->'learning_order')<>jsonb_array_length(s->'subquestions')
   or (select count(distinct value) from jsonb_array_elements_text(s->'learning_order'))<>jsonb_array_length(s->'subquestions')
   or exists(select 1 from jsonb_array_elements_text(s->'learning_order') code where not exists(select 1 from jsonb_array_elements(s->'subquestions') sub where sub->>'id'=code)) then raise exception 'Learning order must be a complete permutation'; end if;
  -- Content address excludes only mutable publishing/review labels.
  content_hash:=encode(sha256(convert_to(jsonb_build_object('question_set',jsonb_set(s-'status','{verification}',(s->'verification')-'review_status'),
   'applicability',coalesce(p_payload->'applicability','{}'))::text,'UTF8')),'hex');
  insert into public.cpa_question_sets(id) values(s->>'id') on conflict(id) do nothing;
  select v.id into version_id from public.cpa_question_set_versions v where v.set_id=s->>'id' and v.content_hash=content_hash and v.sealed_at is not null order by v.revision desc limit 1;
  if version_id is not null then
   insert into public.cpa_question_bank_release_items(release_id,set_id,set_version_id,position) values(release_id,s->>'id',version_id,item.position);
   continue;
  end if;
  select sum((cr->>'max_points')::int)::int into set_points from jsonb_array_elements(s->'subquestions') sub cross join lateral jsonb_array_elements(sub->'criteria') cr;
  select coalesce(max(v.revision),0)+1 into revision_no from public.cpa_question_set_versions v where v.set_id=s->>'id';
  insert into public.cpa_question_set_versions(set_id,revision,schema_version,status,title,topic_id,part,chapter,domain,standards,tags,shared_facts,source_fidelity,review_status,calculation_required,verification_notes,applicability,content_hash,max_points)
  values(s->>'id',revision_no,'3.0','needs_review',s->>'title',s#>>'{classification,topic_id}',s#>>'{classification,part}',s#>>'{classification,chapter}',s#>>'{classification,domain}',public.cpa_json_text_array(s#>'{classification,standards}'),public.cpa_json_text_array(s#>'{classification,tags}'),facts,s#>>'{verification,source_fidelity}','needs_human_review',false,public.cpa_json_text_array(s#>'{verification,notes}'),coalesce(p_payload->'applicability','{}'),content_hash,set_points)
  returning id into version_id;

  for source_item in select value,ordinality::int as position from jsonb_array_elements(s->'source_refs') with ordinality loop
   insert into public.cpa_question_sources(set_version_id,code,position,file_path,title,page_label,role,source_quote,declared_quote_hash,quote_hash)
   values(version_id,source_item.value->>'id',source_item.position,source_item.value->>'file',source_item.value->>'title',source_item.value->>'page',source_item.value->>'role',source_item.value->>'source_quote',source_item.value->>'content_hash',encode(sha256(convert_to(source_item.value->>'source_quote','UTF8')),'hex'));
  end loop;
  if exists(select 1 from public.cpa_question_sources src where src.set_version_id=version_id group by public.cpa_normalize_fact(src.source_quote) having count(*)>1) then raise exception 'Duplicate source quote inside set'; end if;

  for sq in select value,ordinality::int as position from jsonb_array_elements(s->'subquestions') with ordinality loop
   q:=sq.value;
   if q ? 'question_style' and (jsonb_typeof(q->'question_style') is distinct from 'string'
     or q->>'question_style' not in ('standard','case')) then raise exception 'Invalid authored question style'; end if;
   if q ? 'topic_ids' then
     perform public.cpa_json_text_array(q->'topic_ids');
     if jsonb_array_length(q->'topic_ids')=0
       or exists(select 1 from jsonb_array_elements_text(q->'topic_ids') t where t !~ '^(0[1-9]|1[0-9])$')
       or jsonb_array_length(q->'topic_ids')<>(select count(distinct t) from jsonb_array_elements_text(q->'topic_ids') t)
